-- =====================================================================================
-- Evidence for the Risk Officers' review of the discovery list, snapshot @@SNAP_DATE@@
-- GENERATED by: python main.py review. Contains TINs: never commit or share outside the team.
--
-- For each listed taxpayer, the declarations whose price sits furthest below what other importers
-- declare for the same tariff line and origin, with the entry reference to look them up.
-- Light enough for Hue: only the listed taxpayers' items and the tariff lines they used are read.
-- History window: declarations after @@HIST_START@@ up to @@SNAP@@.
-- The benchmark is a reason to look, not a customs value (valuation follows the methods in order).
-- Fuel (HS 27) is left out: it is priced per litre with specific duties, so a price per kg misleads.
-- Where a quantity in units is declared, an entry counts only if it is also below peers per unit.
-- =====================================================================================
WITH mine_raw AS (
  SELECT v.taxpayer_tin, v.clearance_station_cd, v.entry_num, v.dec_ref_yer, v.assessment_dt_wid,
         v.instance_id, v.key_itm_nbr, v.hsc_cd, v.gds_org_cty, v.cpc_cd, v.customs_value,
         v.net_weight, v.supplementary_qnty, v.tax_assessed,
         ROW_NUMBER() OVER (PARTITION BY v.instance_id, v.key_itm_nbr ORDER BY v.assessment_dt_wid) AS rn
  FROM dm_modeled_ura_datascience.vw_cstm_AEO_model v
  WHERE v.assessment_dt_wid >  '@@HIST_START@@'
    AND v.assessment_dt_wid <= '@@SNAP@@'
    AND v.regime_cd IN ('IM4', 'IM7')
    AND v.decl_status <> 'Cancelled'
    AND v.taxpayer_tin IN (@@TINS@@)
),

mine AS (SELECT * FROM mine_raw
         WHERE rn = 1 AND customs_value > 0 AND net_weight > 0 AND substr(hsc_cd, 1, 2) <> '27'),

codes AS (SELECT DISTINCT hsc_cd FROM mine),

-- every importer's items on those tariff lines (identical duplicate rows kept once)
peers AS (
  SELECT DISTINCT v.instance_id, v.key_itm_nbr, v.taxpayer_tin, v.hsc_cd, v.gds_org_cty, v.cpc_cd,
         v.customs_value, v.net_weight, v.supplementary_qnty, v.tax_assessed
  FROM dm_modeled_ura_datascience.vw_cstm_AEO_model v
  JOIN codes c ON v.hsc_cd = c.hsc_cd
  WHERE v.assessment_dt_wid >  '@@HIST_START@@'
    AND v.assessment_dt_wid <= '@@SNAP@@'
    AND v.regime_cd IN ('IM4', 'IM7')
    AND v.decl_status <> 'Cancelled'
    AND v.customs_value > 0 AND v.net_weight > 0
),

bench_ho AS (
  SELECT hsc_cd, gds_org_cty, percentile_approx(customs_value / net_weight, 0.5) AS med_kg,
         COUNT(DISTINCT taxpayer_tin) AS importers
  FROM peers GROUP BY hsc_cd, gds_org_cty HAVING COUNT(DISTINCT taxpayer_tin) >= 5
),
bench_h AS (
  SELECT hsc_cd, percentile_approx(customs_value / net_weight, 0.5) AS med_kg,
         COUNT(DISTINCT taxpayer_tin) AS importers
  FROM peers GROUP BY hsc_cd HAVING COUNT(DISTINCT taxpayer_tin) >= 5
),
bench_u AS (
  SELECT hsc_cd, percentile_approx(customs_value / supplementary_qnty, 0.5) AS med_unit
  FROM peers WHERE supplementary_qnty > 0
  GROUP BY hsc_cd HAVING COUNT(DISTINCT taxpayer_tin) >= 5
),
rate_h AS (
  SELECT hsc_cd, percentile_approx(tax_assessed / customs_value, 0.5) AS med_rate
  FROM peers WHERE cpc_cd = '000' GROUP BY hsc_cd HAVING COUNT(DISTINCT taxpayer_tin) >= 5
),

ev AS (
  SELECT m.taxpayer_tin, m.clearance_station_cd AS station, m.dec_ref_yer AS entry_year, m.entry_num,
         to_date(m.assessment_dt_wid, 'yyyyMMdd') AS assessed_on, m.hsc_cd, m.gds_org_cty AS origin,
         m.cpc_cd AS apc, m.customs_value, m.net_weight, m.supplementary_qnty,
         m.customs_value / m.net_weight                                   AS declared_ugx_per_kg,
         COALESCE(o.med_kg, h.med_kg)                                     AS peers_median_ugx_per_kg,
         CASE WHEN o.med_kg IS NOT NULL THEN 'same line and origin' ELSE 'same line, all origins' END AS benchmark_basis,
         COALESCE(o.importers, h.importers)                               AS importers_in_benchmark,
         (m.customs_value / m.net_weight) / COALESCE(o.med_kg, h.med_kg)  AS price_vs_peers,
         GREATEST(COALESCE(o.med_kg, h.med_kg) * m.net_weight - m.customs_value, 0) AS value_gap_ugx,
         CASE WHEN m.supplementary_qnty > 0 THEN m.customs_value / m.supplementary_qnty END AS declared_ugx_per_unit,
         u.med_unit                                                       AS peers_median_ugx_per_unit,
         m.tax_assessed / m.customs_value                                 AS duty_rate,
         r.med_rate                                                       AS peers_median_duty_rate
  FROM mine m
  LEFT JOIN bench_ho o ON m.hsc_cd = o.hsc_cd AND m.gds_org_cty = o.gds_org_cty
  LEFT JOIN bench_h h  ON m.hsc_cd = h.hsc_cd
  LEFT JOIN rate_h r   ON m.hsc_cd = r.hsc_cd
  LEFT JOIN bench_u u  ON m.hsc_cd = u.hsc_cd
  WHERE COALESCE(o.med_kg, h.med_kg) IS NOT NULL
),

ranked AS (
  SELECT e.*, ROW_NUMBER() OVER (PARTITION BY taxpayer_tin ORDER BY value_gap_ugx DESC) AS evidence_rank
  FROM ev e
  WHERE price_vs_peers >= 0.01          -- below 1% of peers is a keying error, not evidence
    AND price_vs_peers < 1
    AND (declared_ugx_per_unit IS NULL OR peers_median_ugx_per_unit IS NULL
         OR declared_ugx_per_unit < peers_median_ugx_per_unit)
)

SELECT * FROM ranked WHERE evidence_rank <= @@PER_TAXPAYER@@ ORDER BY taxpayer_tin, evidence_rank
